beforeExample:
package test;

public class MyClass {
    public String getFormattedCount(int count) {
        Object[] args = { "Label", new Integer(count) };
        return "Formatted: " + args[1];
    }
}

afterExample:
package test;

public class MyClass {
    public String getFormattedCount(int count) {
        Object[] args = { "Label", java.lang.Integer.valueOf(count) };
        return "Formatted: " + args[1];
    }
}

